declare_node_union! {
    /// A node that represents a scope containing test/hook calls:
    /// either the top-level module/script, or a `describe(...)` call.
    pub AnyTestHookScope = JsModule | JsScript | JsCallExpression
}

impl Rule for UseTestHooksOnTop {
    type Query = Ast<AnyTestHookScope>;
    type State = JsCallExpression;
    type Signals = Vec<Self::State>;
    type Options = UseTestHooksOnTopOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let scope = ctx.query();

        // For a call expression, only act when it is a describe block, and
        // check the statements of its callback body.
        if let AnyTestHookScope::JsCallExpression(call) = scope {
            if !is_describe_call(call) {
                return vec![];
            }
            let Some(stmts) = describe_body_statements(call) else {
                return vec![];
            };
            return check_direct_children(&stmts);
        }

        // For the top-level module or script, gather the top-level statements.
        let stmts: Vec<AnyJsStatement> = match scope {
            AnyTestHookScope::JsModule(module) => module
                .items()
                .into_iter()
                .filter_map(|item| {
                    if let AnyJsModuleItem::AnyJsStatement(stmt) = item {
                        Some(stmt)
                    } else {
                        None
                    }
                })
                .collect(),
            AnyTestHookScope::JsScript(script) => script.statements().into_iter().collect(),
            AnyTestHookScope::JsCallExpression(_) => unreachable!(),
        };
        check_direct_children(&stmts)
    }

    fn diagnostic(_: &RuleContext<Self>, node: &Self::State) -> Option<RuleDiagnostic> {
        let hook_name = hook_name(node)?;

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Lifecycle hook "{hook_name.text()}" appears after a test case."
                },
            )
            .note(markup! {
                "Placing the hook after this test case makes it harder to spot the setup and teardown for these tests at a glance."
            })
            .note(markup! {
                "Move the hook above all test cases in the same block for better readability."
            }),
        )
    }
}

/// Checks a flat list of statements, in source order, for lifecycle hooks that
/// appear after a test case in the same scope.
///
/// Only looks at the **direct children** of the current scope — nested
/// `describe` blocks are handled by the query firing again for each of them.
///
/// Returns every hook call that appears after at least one test case.
fn check_direct_children(statements: &[AnyJsStatement]) -> Vec<JsCallExpression> {
    let mut seen_test = false;
    let mut invalid = vec![];

    for stmt in statements {
        let Some(call) = call_from_statement(stmt) else {
            continue;
        };

        if is_test_case_call(&call) {
            seen_test = true;
        } else if seen_test && is_hook_call(&call) {
            invalid.push(call);
        }
    }

    invalid
}

/// Returns the list of direct-child statements from the callback passed to a
/// `describe(...)` call, or `None` if the callback is not a recognisable
/// function literal with a block body.
fn describe_body_statements(call: &JsCallExpression) -> Option<Vec<AnyJsStatement>> {
    let args = call.arguments().ok()?;
    let [_, callback_arg] = args.get_arguments_by_index([0, 1]);
    let callback_arg = callback_arg?;
    let expr = callback_arg.as_any_js_expression()?;

    let body = match expr {
        AnyJsExpression::JsArrowFunctionExpression(arrow) => arrow.body().ok()?,
        AnyJsExpression::JsFunctionExpression(func) => {
            AnyJsFunctionBody::JsFunctionBody(func.body().ok()?)
        }
        _ => return None,
    };

    let AnyJsFunctionBody::JsFunctionBody(block) = body else {
        return None;
    };

    Some(block.statements().into_iter().collect())
}

/// Extracts the (single) `JsCallExpression` from an expression statement, if
/// the statement is of the form `call_expr(...)`.
fn call_from_statement(stmt: &AnyJsStatement) -> Option<JsCallExpression> {
    let expr_stmt = stmt.as_js_expression_statement()?;
    let expr = expr_stmt.expression().ok()?;
    expr.as_js_call_expression().cloned()
}

/// Returns `true` if the call is a test case: `it(...)` or `test(...)`.
fn is_test_case_call(call: &JsCallExpression) -> bool {
    matches!(callee_identifier(call).as_deref(), Some("it" | "test"))
}

/// Returns `true` if the call is a lifecycle hook.
fn is_hook_call(call: &JsCallExpression) -> bool {
    hook_name(call).is_some()
}

/// Returns the lifecycle hook name of the call, if its callee is one of the
/// recognized hooks.
fn hook_name(call: &JsCallExpression) -> Option<biome_rowan::TokenText> {
    let name = callee_identifier_token(call)?;
    matches!(
        name.text(),
        "beforeAll" | "beforeEach" | "afterEach" | "afterAll" | "before" | "after"
    )
    .then_some(name)
}

/// Returns the plain identifier callee name of the call as text, if any.
fn callee_identifier(call: &JsCallExpression) -> Option<String> {
    callee_identifier_token(call).map(|name| name.text().to_string())
}

